WITH valid AS (SELECT *, CASE WHEN quantity >= 228 THEN 'High' WHEN quantity >= 71 THEN 'Medium' ELSE 'Low' END AS quantity_band FROM inventory WHERE last_restock >= '2024-12-31') SELECT CASE WHEN quantity >= 251 THEN 'PREMIUM' ELSE 'STANDARD' END AS quantity_tier, STDDEV_SAMP(quantity) AS quantity_stddev, ROUND(AVG(quantity), 2) AS avg_quantity, AVG(quantity) AS avg_quantity_2, BIT_AND(quantity) AS quantity_bit_and FROM valid GROUP BY 1 ORDER BY avg_quantity DESC NULLS FIRST
